#!/usr/bin/env python3
import sys, re, threading

sys.set_int_max_str_digits(0)
sys.setrecursionlimit(10**7)


class PErr(Exception):
    pass


class TErr(Exception):
    pass


KEYWORDS = {'let', 'rec', 'in', 'if', 'then', 'else'}
RESERVED = {'match', 'with', 'type', 'forall'}

TOK_RE = re.compile(r'''
 (?P<ws>[ \t\n\r\f\v]+)
|(?P<com>--[^\n]*)
|(?P<int>[0-9]+)
|(?P<id>[a-z_][A-Za-z0-9_]*)
|(?P<up>[A-Z][A-Za-z0-9_]*)
|(?P<sym>->|//|==|[()/+\-*%<=:])
''', re.X)


def lex(src):
    toks = []
    pos = 0
    n = len(src)
    m = TOK_RE.match
    while pos < n:
        mo = m(src, pos)
        if not mo:
            raise PErr('bad char %r' % src[pos])
        k = mo.lastgroup
        s = mo.group()
        pos = mo.end()
        if k == 'ws' or k == 'com':
            continue
        if k == 'int':
            toks.append(('INT', int(s)))
        elif k == 'id':
            if s == '_' or s in RESERVED:
                raise PErr('bad ident')
            if s in KEYWORDS:
                toks.append((s, None))
            else:
                toks.append(('ID', s))
        elif k == 'up':
            if s in ('True', 'False', 'Int', 'Bool'):
                toks.append((s, None))
            else:
                raise PErr('bad name')
        else:
            toks.append((s, None))
    toks.append(('EOF', None))
    return toks


# AST: ('int',v) ('bool',v) ('var',name) ('lam',x,body) ('app',f,a)
# ('bin',op,a,b) ('if',c,t,e) ('anno',e,T) ('let',x,T|None,e1,e2) ('letrec',f,T,lam,e2)

class Parser:
    def __init__(self, toks):
        self.t = toks
        self.i = 0

    def peek(self):
        return self.t[self.i][0]

    def eat(self, k):
        tok = self.t[self.i]
        if tok[0] != k:
            raise PErr('expected %s got %s' % (k, tok[0]))
        self.i += 1
        return tok[1]

    def program(self):
        e = self.expr()
        self.eat('EOF')
        return e

    def expr(self):
        k = self.peek()
        if k == '/':
            self.i += 1
            x = self.eat('ID')
            self.eat('->')
            return ('lam', x, self.expr())
        if k == 'let':
            self.i += 1
            if self.peek() == 'rec':
                self.i += 1
                f = self.eat('ID')
                self.eat(':')
                T = self.type()
                self.eat('=')
                e1 = self.expr()
                lam = e1
                while lam[0] == 'paren':
                    lam = lam[1]
                if lam[0] != 'lam':
                    raise PErr('let rec needs lambda')
                self.eat('in')
                e2 = self.expr()
                return ('letrec', f, T, lam, e2)
            x = self.eat('ID')
            T = None
            if self.peek() == ':':
                self.i += 1
                T = self.type()
            self.eat('=')
            e1 = self.expr()
            self.eat('in')
            e2 = self.expr()
            return ('let', x, T, e1, e2)
        if k == 'if':
            self.i += 1
            c = self.expr()
            self.eat('then')
            a = self.expr()
            self.eat('else')
            b = self.expr()
            return ('if', c, a, b)
        return self.cmp()

    def cmp(self):
        a = self.add()
        k = self.peek()
        if k == '==' or k == '<':
            self.i += 1
            b = self.add()
            a = ('bin', k, a, b)
        return a

    def add(self):
        a = self.mul()
        while True:
            k = self.peek()
            if k == '+' or k == '-':
                self.i += 1
                a = ('bin', k, a, self.mul())
            else:
                return a

    def mul(self):
        a = self.app()
        while True:
            k = self.peek()
            if k == '*' or k == '//' or k == '%':
                self.i += 1
                a = ('bin', k, a, self.app())
            else:
                return a

    ATOM_START = {'ID', 'INT', 'True', 'False', '('}

    def app(self):
        a = self.atom()
        while self.peek() in self.ATOM_START:
            a = ('app', a, self.atom())
        return a

    def atom(self):
        tok = self.t[self.i]
        k = tok[0]
        if k == 'ID':
            self.i += 1
            return ('var', tok[1])
        if k == 'INT':
            self.i += 1
            return ('int', tok[1])
        if k == 'True':
            self.i += 1
            return ('bool', True)
        if k == 'False':
            self.i += 1
            return ('bool', False)
        if k == '(':
            self.i += 1
            e = self.expr()
            if self.peek() == ':':
                self.i += 1
                T = self.type()
                self.eat(')')
                return ('anno', e, T)
            self.eat(')')
            return ('paren', e)
        raise PErr('unexpected %s' % k)

    def type(self):
        a = self.tatom()
        if self.peek() == '->':
            self.i += 1
            return ('->', a, self.type())
        return a

    def tatom(self):
        k = self.peek()
        if k == 'Int' or k == 'Bool':
            self.i += 1
            return k
        if k == '(':
            self.i += 1
            t = self.type()
            self.eat(')')
            return t
        raise PErr('bad type')


# ---------------- typechecking (HM unification) ----------------

class TV:
    __slots__ = ('ref',)

    def __init__(self):
        self.ref = None


def prune(t):
    while isinstance(t, TV) and t.ref is not None:
        t = t.ref
    return t


def occurs(v, t):
    stack = [t]
    while stack:
        t = prune(stack.pop())
        if t is v:
            return True
        if isinstance(t, tuple):
            stack.append(t[1])
            stack.append(t[2])
    return False


def unify(a, b):
    stack = [(a, b)]
    while stack:
        a, b = stack.pop()
        a = prune(a)
        b = prune(b)
        if a is b:
            continue
        if isinstance(a, TV):
            if occurs(a, b):
                raise TErr('occurs')
            a.ref = b
            continue
        if isinstance(b, TV):
            if occurs(b, a):
                raise TErr('occurs')
            b.ref = a
            continue
        if isinstance(a, str) or isinstance(b, str):
            if a != b:
                raise TErr('mismatch %s %s' % (a, b))
            continue
        stack.append((a[1], b[1]))
        stack.append((a[2], b[2]))


def infer(e, env):
    # env: dict name -> list of types (stack)
    k = e[0]
    if k == 'int':
        return 'Int'
    if k == 'bool':
        return 'Bool'
    if k == 'var':
        s = env.get(e[1])
        if not s:
            raise TErr('unbound ' + e[1])
        return s[-1]
    if k == 'paren':
        return infer(e[1], env)
    if k == 'lam':
        a = TV()
        env.setdefault(e[1], []).append(a)
        r = infer(e[2], env)
        env[e[1]].pop()
        return ('->', a, r)
    if k == 'app':
        f = infer(e[1], env)
        x = infer(e[2], env)
        f = prune(f)
        if isinstance(f, tuple):
            unify(f[1], x)
            return f[2]
        r = TV()
        unify(f, ('->', x, r))
        return r
    if k == 'bin':
        unify(infer(e[2], env), 'Int')
        unify(infer(e[3], env), 'Int')
        return 'Bool' if e[1] in ('==', '<') else 'Int'
    if k == 'if':
        unify(infer(e[1], env), 'Bool')
        t = infer(e[2], env)
        unify(t, infer(e[3], env))
        return t
    if k == 'anno':
        unify(infer(e[1], env), e[2])
        return e[2]
    if k == 'let':
        t = infer(e[3], env)
        if e[2] is not None:
            unify(t, e[2])
            t = e[2]
        env.setdefault(e[1], []).append(t)
        r = infer(e[4], env)
        env[e[1]].pop()
        return r
    if k == 'letrec':
        T = e[2]
        env.setdefault(e[1], []).append(T)
        unify(infer(e[3], env), T)
        r = infer(e[4], env)
        env[e[1]].pop()
        return r
    raise TErr('?')


# ---------------- compile to indexed nodes ----------------
# node kinds
INT, VAR, LAM, APP, BIN, IF, LET, LETREC = range(8)
ADD, SUB, MUL, DIV, MOD, EQ, LT = range(7)
OPS = {'+': ADD, '-': SUB, '*': MUL, '//': DIV, '%': MOD, '==': EQ, '<': LT}


def compile_(e, scope):
    # scope: list of names; index = distance from end
    while True:
        k = e[0]
        if k == 'paren' or k == 'anno':
            e = e[1]
            continue
        break
    if k == 'int' or k == 'bool':
        return (INT, e[1])
    if k == 'var':
        name = e[1]
        i = len(scope) - 1
        while scope[i] != name:
            i -= 1
        return (VAR, len(scope) - 1 - i)
    if k == 'lam':
        scope.append(e[1])
        b = compile_(e[2], scope)
        scope.pop()
        return (LAM, b)
    if k == 'app':
        return (APP, compile_(e[1], scope), compile_(e[2], scope))
    if k == 'bin':
        return (BIN, OPS[e[1]], compile_(e[2], scope), compile_(e[3], scope))
    if k == 'if':
        return (IF, compile_(e[1], scope), compile_(e[2], scope), compile_(e[3], scope))
    if k == 'let':
        a = compile_(e[3], scope)
        scope.append(e[1])
        b = compile_(e[4], scope)
        scope.pop()
        return (LET, a, b)
    if k == 'letrec':
        scope.append(e[1])
        lam = e[3]
        scope.append(lam[1])
        body = compile_(lam[2], scope)
        scope.pop()
        b = compile_(e[4], scope)
        scope.pop()
        return (LETREC, body, b)
    raise Exception('?')


class Clo:
    __slots__ = ('body', 'env')

    def __init__(self, body, env):
        self.body = body
        self.env = env


def ev(n, env):
    # env: linked list [value, parent]
    while True:
        t = n[0]
        if t == VAR:
            k = n[1]
            while k:
                env = env[1]
                k -= 1
            return env[0]
        if t == INT:
            return n[1]
        if t == BIN:
            op = n[1]
            a = ev(n[2], env)
            b = ev(n[3], env)
            if op == ADD:
                return a + b
            if op == SUB:
                return a - b
            if op == MUL:
                return a * b
            if op == LT:
                return a < b
            if op == EQ:
                return a == b
            if op == DIV:
                return a // b
            return a % b
        if t == APP:
            f = ev(n[1], env)
            a = ev(n[2], env)
            n = f.body
            env = [a, f.env]
            continue
        if t == IF:
            if ev(n[1], env):
                n = n[2]
            else:
                n = n[3]
            continue
        if t == LAM:
            return Clo(n[1], env)
        if t == LET:
            env = [ev(n[1], env), env]
            n = n[2]
            continue
        if t == LETREC:
            env = [None, env]
            env[0] = Clo(n[1], env)
            n = n[2]
            continue
        raise Exception('bad node')


def main():
    out = sys.stdout
    try:
        with open(sys.argv[2], 'rb') as f:
            data = f.read()
        try:
            if any(b > 127 for b in data):
                raise PErr('non-ascii')
            src = data.decode('ascii')
            ast = Parser(lex(src)).program()
        except (PErr, RecursionError, ValueError) as ex:
            out.write('ParseError: %s\n' % ex)
            return 1
        try:
            infer(ast, {})
        except (TErr, RecursionError) as ex:
            out.write('TypeError: %s\n' % ex)
            return 1
        code = compile_(ast, [])
        try:
            v = ev(code, None)
        except ZeroDivisionError:
            out.write('RuntimeError: division by zero\n')
            return 1
        if v is True:
            s = 'True'
        elif v is False:
            s = 'False'
        elif isinstance(v, Clo):
            s = '<function>'
        else:
            s = str(v)
        out.write(s + '\n')
        return 0
    finally:
        out.flush()


if __name__ == '__main__':
    if len(sys.argv) != 3 or sys.argv[1] != 'run':
        sys.stderr.write('usage: minicore run FILE\n')
        sys.exit(2)
    threading.stack_size(1024 * 1024 * 1024)
    res = [1]

    def runner():
        res[0] = main()
    th = threading.Thread(target=runner)
    th.start()
    th.join()
    sys.stdout.flush()
    import os
    os._exit(res[0])

